421	
422	## Config Trait Pattern — Taming Generic Parameter Explosion
423	
424	### The Problem
425	
426	As a struct takes on more responsibilities, each backed by a trait-constrained generic,
427	the type signature grows unwieldy:
428	
429	```rust
430	trait SpiBus   { fn spi_transfer(&self, tx: &[u8], rx: &mut [u8]) -> Result<(), BusError>; }
431	trait ComPort  { fn com_send(&self, data: &[u8]) -> Result<usize, BusError>; }
432	trait I3cBus   { fn i3c_read(&self, addr: u8, buf: &mut [u8]) -> Result<(), BusError>; }
433	trait SmBus    { fn smbus_read_byte(&self, addr: u8, cmd: u8) -> Result<u8, BusError>; }
434	trait GpioBus  { fn gpio_set(&self, pin: u32, high: bool); }
435	
436	// ❌ Every new bus trait adds another generic parameter
437	struct DiagController<S: SpiBus, C: ComPort, I: I3cBus, M: SmBus, G: GpioBus> {
438	    spi: S,
439	    com: C,
440	    i3c: I,
441	    smbus: M,
442	    gpio: G,
443	}
444	// impl blocks, function signatures, and callers all repeat the full list.
445	// Adding a 6th bus means editing every mention of DiagController<S, C, I, M, G>.
446	```
447	
448	This is often called **"generic parameter explosion."** It compounds across `impl` blocks,
449	function parameters, and downstream consumers — each of which must repeat the full
450	parameter list.
451	
452	### The Solution: A Config Trait
453	
454	Bundle all associated types into a single trait. The struct then has **one** generic
455	parameter regardless of how many component types it contains:
456	
457	```rust
458	#[derive(Debug)]
459	enum BusError {
460	    Timeout,
461	    NakReceived,
462	    HardwareFault(String),
463	}
464	
465	// --- Bus traits (unchanged) ---
466	trait SpiBus {
467	    fn spi_transfer(&self, tx: &[u8], rx: &mut [u8]) -> Result<(), BusError>;
468	    fn spi_write(&self, data: &[u8]) -> Result<(), BusError>;
469	}
470	
471	trait ComPort {
472	    fn com_send(&self, data: &[u8]) -> Result<usize, BusError>;
473	    fn com_recv(&self, buf: &mut [u8], timeout_ms: u32) -> Result<usize, BusError>;
474	}
475	
476	trait I3cBus {
477	    fn i3c_read(&self, addr: u8, buf: &mut [u8]) -> Result<(), BusError>;
478	    fn i3c_write(&self, addr: u8, data: &[u8]) -> Result<(), BusError>;
479	}
480	
481	// --- The Config trait: one associated type per component ---
482	trait BoardConfig {
483	    type Spi: SpiBus;
484	    type Com: ComPort;
485	    type I3c: I3cBus;
486	}
487	
488	// --- DiagController has exactly ONE generic parameter ---
489	struct DiagController<Cfg: BoardConfig> {
490	    spi: Cfg::Spi,
491	    com: Cfg::Com,
492	    i3c: Cfg::I3c,
493	}
494	```
495	
496	`DiagController<Cfg>` will never gain another generic parameter.
497	Adding a 4th bus means adding one associated type to `BoardConfig` and one field
498	to `DiagController` — no downstream signature changes.
499	
500	### Implementing the Controller
501	
502	```rust
503	impl<Cfg: BoardConfig> DiagController<Cfg> {
504	    fn new(spi: Cfg::Spi, com: Cfg::Com, i3c: Cfg::I3c) -> Self {
505	        DiagController { spi, com, i3c }
506	    }
507	
508	    fn read_flash_id(&self) -> Result<u32, BusError> {
509	        let cmd = [0x9F]; // JEDEC Read ID
510	        let mut id = [0u8; 4];
511	        self.spi.spi_transfer(&cmd, &mut id)?;
512	        Ok(u32::from_be_bytes(id))
513	    }
514	
515	    fn send_bmc_command(&self, cmd: &[u8]) -> Result<Vec<u8>, BusError> {
516	        self.com.com_send(cmd)?;
517	        let mut resp = vec![0u8; 256];
518	        let n = self.com.com_recv(&mut resp, 1000)?;
519	        resp.truncate(n);
520	        Ok(resp)
521	    }
522	
523	    fn read_sensor_temp(&self, sensor_addr: u8) -> Result<i16, BusError> {
524	        let mut buf = [0u8; 2];
525	        self.i3c.i3c_read(sensor_addr, &mut buf)?;
526	        Ok(i16::from_be_bytes(buf))
527	    }
528	
529	    fn run_full_diag(&self) -> Result<DiagReport, BusError> {
530	        let flash_id = self.read_flash_id()?;
531	        let bmc_resp = self.send_bmc_command(b"VERSION\n")?;
532	        let cpu_temp = self.read_sensor_temp(0x48)?;
533	        let gpu_temp = self.read_sensor_temp(0x49)?;
534	
535	        Ok(DiagReport {
536	            flash_id,
537	            bmc_version: String::from_utf8_lossy(&bmc_resp).to_string(),
538	            cpu_temp_c: cpu_temp,
539	            gpu_temp_c: gpu_temp,
540	        })
541	    }
542	}
543	
544	#[derive(Debug)]
545	struct DiagReport {
546	    flash_id: u32,
547	    bmc_version: String,
548	    cpu_temp_c: i16,
549	    gpu_temp_c: i16,
550	}
551	```
552	
553	### Production Wiring
554	
555	One `impl BoardConfig` selects the concrete hardware drivers:
556	
557	```rust
558	struct PlatformSpi  { dev: String, speed_hz: u32 }
559	struct UartCom      { dev: String, baud: u32 }
560	struct LinuxI3c     { dev: String }
561	
562	impl SpiBus for PlatformSpi {
563	    fn spi_transfer(&self, tx: &[u8], rx: &mut [u8]) -> Result<(), BusError> {
564	        // ioctl(SPI_IOC_MESSAGE) in production
565	        rx[0..4].copy_from_slice(&[0xEF, 0x40, 0x18, 0x00]);
566	        Ok(())
567	    }
568	    fn spi_write(&self, _data: &[u8]) -> Result<(), BusError> { Ok(()) }
569	}
570	
571	impl ComPort for UartCom {
572	    fn com_send(&self, _data: &[u8]) -> Result<usize, BusError> { Ok(0) }
573	    fn com_recv(&self, buf: &mut [u8], _timeout: u32) -> Result<usize, BusError> {
574	        let resp = b"BMC v2.4.1\n";
575	        buf[..resp.len()].copy_from_slice(resp);
576	        Ok(resp.len())
577	    }
578	}
579	
580	impl I3cBus for LinuxI3c {
581	    fn i3c_read(&self, _addr: u8, buf: &mut [u8]) -> Result<(), BusError> {
582	        buf[0] = 0x00; buf[1] = 0x2D; // 45°C
583	        Ok(())
584	    }
585	    fn i3c_write(&self, _addr: u8, _data: &[u8]) -> Result<(), BusError> { Ok(()) }
586	}
587	
588	// ✅ One struct, one impl — all concrete types resolved here
589	struct ProductionBoard;
590	impl BoardConfig for ProductionBoard {
591	    type Spi = PlatformSpi;
592	    type Com = UartCom;
593	    type I3c = LinuxI3c;
594	}
595	
596	fn main() {
597	    let ctrl = DiagController::<ProductionBoard>::new(
598	        PlatformSpi { dev: "/dev/spidev0.0".into(), speed_hz: 10_000_000 },
599	        UartCom     { dev: "/dev/ttyS0".into(),     baud: 115200 },
600	        LinuxI3c    { dev: "/dev/i3c-0".into() },
601	    );
602	    let report = ctrl.run_full_diag().unwrap();
603	    println!("{report:#?}");
604	}
605	```
606	
607	### Test Wiring with Mocks
608	
609	Swap the entire hardware layer by defining a different `BoardConfig`:
610	
611	```rust
612	struct MockSpi  { flash_id: [u8; 4] }
613	struct MockCom  { response: Vec<u8> }
614	struct MockI3c  { temps: std::collections::HashMap<u8, i16> }
615	
616	impl SpiBus for MockSpi {
617	    fn spi_transfer(&self, _tx: &[u8], rx: &mut [u8]) -> Result<(), BusError> {
618	        rx[..4].copy_from_slice(&self.flash_id);
619	        Ok(())
620	    }
621	    fn spi_write(&self, _data: &[u8]) -> Result<(), BusError> { Ok(()) }
622	}
623	
624	impl ComPort for MockCom {
625	    fn com_send(&self, _data: &[u8]) -> Result<usize, BusError> { Ok(0) }
626	    fn com_recv(&self, buf: &mut [u8], _timeout: u32) -> Result<usize, BusError> {
627	        let n = self.response.len().min(buf.len());
628	        buf[..n].copy_from_slice(&self.response[..n]);
629	        Ok(n)
630	    }
631	}
632	
633	impl I3cBus for MockI3c {
634	    fn i3c_read(&self, addr: u8, buf: &mut [u8]) -> Result<(), BusError> {
635	        let temp = self.temps.get(&addr).copied().unwrap_or(0);
636	        buf[..2].copy_from_slice(&temp.to_be_bytes());
637	        Ok(())
638	    }
639	    fn i3c_write(&self, _addr: u8, _data: &[u8]) -> Result<(), BusError> { Ok(()) }
640	}
641	
642	struct TestBoard;
643	impl BoardConfig for TestBoard {
644	    type Spi = MockSpi;
645	    type Com = MockCom;
646	    type I3c = MockI3c;
647	}
648	
649	#[cfg(test)]
650	mod tests {
651	    use super::*;
652	
653	    fn make_test_controller() -> DiagController<TestBoard> {
654	        let mut temps = std::collections::HashMap::new();
655	        temps.insert(0x48, 45i16);
656	        temps.insert(0x49, 72i16);
657	
658	        DiagController::<TestBoard>::new(
659	            MockSpi  { flash_id: [0xEF, 0x40, 0x18, 0x00] },
660	            MockCom  { response: b"BMC v2.4.1\n".to_vec() },
661	            MockI3c  { temps },
662	        )
663	    }
664	
665	    #[test]
666	    fn test_flash_id() {
667	        let ctrl = make_test_controller();
668	        assert_eq!(ctrl.read_flash_id().unwrap(), 0xEF401800);
669	    }
670	
671	    #[test]
672	    fn test_sensor_temps() {
673	        let ctrl = make_test_controller();
674	        assert_eq!(ctrl.read_sensor_temp(0x48).unwrap(), 45);
675	        assert_eq!(ctrl.read_sensor_temp(0x49).unwrap(), 72);
676	    }
677	
678	    #[test]
679	    fn test_full_diag() {
680	        let ctrl = make_test_controller();
681	        let report = ctrl.run_full_diag().unwrap();
682	        assert_eq!(report.flash_id, 0xEF401800);
683	        assert_eq!(report.cpu_temp_c, 45);
684	        assert_eq!(report.gpu_temp_c, 72);
685	        assert!(report.bmc_version.contains("2.4.1"));
686	    }
687	}
688	```
689	
690	### Adding a New Bus Later
691	
692	When you need a 4th bus, only two things change — `BoardConfig` and `DiagController`.
693	**No downstream signature changes.** The generic parameter count stays at one:
694	
695	```rust
696	trait SmBus {
697	    fn smbus_read_byte(&self, addr: u8, cmd: u8) -> Result<u8, BusError>;
698	}
699	
700	// 1. Add one associated type:
701	trait BoardConfig {
702	    type Spi: SpiBus;
703	    type Com: ComPort;
704	    type I3c: I3cBus;
705	    type Smb: SmBus;     // ← new
706	}
707	
708	// 2. Add one field:
709	struct DiagController<Cfg: BoardConfig> {
710	    spi: Cfg::Spi,
711	    com: Cfg::Com,
712	    i3c: Cfg::I3c,
713	    smb: Cfg::Smb,       // ← new
714	}
715	
716	// 3. Provide the concrete type in each config impl:
717	impl BoardConfig for ProductionBoard {
718	    type Spi = PlatformSpi;
719	    type Com = UartCom;
720	    type I3c = LinuxI3c;
721	    type Smb = LinuxSmbus; // ← new
722	}
723	```
724	
725	### When to Use This Pattern
726	
727	| Situation | Use Config Trait? | Alternative |
728	|-----------|:-:|---|
729	| 3+ trait-constrained generics on a struct | ✅ Yes | — |
730	| Need to swap entire hardware/platform layer | ✅ Yes | — |
731	| Only 1-2 generics | ❌ Overkill | Direct generics |
732	| Need runtime polymorphism | ❌ | `dyn Trait` objects |
733	| Open-ended plugin system | ❌ | Type-map / `Any` |
734	| Component traits form a natural group (board, platform) | ✅ Yes | — |
735	
736	### Key Properties
737	
738	- **One generic parameter forever** — `DiagController<Cfg>` never gains more `<A, B, C, ...>`
739	- **Fully static dispatch** — no vtables, no `dyn`, no heap allocation for trait objects
740	- **Clean test swapping** — define `TestBoard` with mock impls, zero conditional compilation
741	- **Compile-time safety** — forget an associated type → compile error, not runtime crash
742	- **Battle-tested** — this is the pattern used by Substrate/Polkadot's frame system
743	  to manage 20+ associated types through a single `Config` trait
744	
745	> **Key Takeaways — Newtype & Type-State**
746	> - Newtypes give compile-time type safety at zero runtime cost
747	> - Type-state makes illegal state transitions a compile error, not a runtime bug
748	> - Config traits tame generic parameter explosion in large systems
749	
750	> **See also:** [Ch 4 — PhantomData](ch04-phantomdata-types-that-carry-no-data.md) for the zero-sized markers that power type-state. [Ch 2 — Traits In Depth](ch02-traits-in-depth.md) for associated types used in the config trait pattern.
751	
752	---
753	
754	## Case Study: Dual-Axis Typestate — Vendor × Protocol State
755	
756	The patterns above handle one axis at a time: typestate enforces *protocol order*,
757	and trait abstraction handles *multiple vendors*. Real systems often need **both
758	simultaneously**: a wrapper `Handle<Vendor, State>` where available methods depend
759	on *which vendor* is plugged in **and** *which state* the handle is in.
760	
761	This section shows the **dual-axis conditional `impl`** pattern — where `impl`
762	blocks are gated on both a vendor trait bound and a state marker trait.
763	
764	### The Two-Dimensional Problem
765	
766	Consider a debug probe interface (JTAG/SWD). Multiple vendors make probes, and
767	every probe must be unlocked before registers become accessible. Some vendors
768	additionally support direct memory reads — but only after an *extended unlock*
769	that configures the memory access port:
770	
771	```mermaid
772	graph LR
773	    subgraph "All vendors"
774	        L["🔒 Locked"] -- "unlock()" --> U["🔓 Unlocked"]
775	    end
776	    subgraph "Memory-capable vendors only"
777	        U -- "extended_unlock()" --> E["🔓🧠 ExtendedUnlocked"]
778	    end
779	
780	    U -. "read_reg() / write_reg()" .-> U
781	    E -. "read_reg() / write_reg()" .-> E
782	    E -. "read_memory() / write_memory()" .-> E
783	
784	    style L fill:#fee,stroke:#c33
785	    style U fill:#efe,stroke:#3a3
786	    style E fill:#eef,stroke:#33c
787	```
788	
789	The **capability matrix** — which methods exist for which (vendor, state)
790	combination — is two-dimensional:
791	
792	```mermaid
793	block-beta
794	    columns 4
795	    space header1["Locked"] header2["Unlocked"] header3["ExtendedUnlocked"]
796	    basic["Basic Vendor"]:1 b1["unlock()"] b2["read_reg()<br/>write_reg()"] b3["— unreachable —"]
797	    memory["Memory Vendor"]:1 m1["unlock()"] m2["read_reg()<br/>write_reg()<br/>extended_unlock()"] m3["read_reg()<br/>write_reg()<br/>read_memory()<br/>write_memory()"]
798	
799	    style b1 fill:#ffd,stroke:#aa0
800	    style b2 fill:#efe,stroke:#3a3
801	    style b3 fill:#eee,stroke:#999,stroke-dasharray: 5 5
802	    style m1 fill:#ffd,stroke:#aa0
803	    style m2 fill:#efe,stroke:#3a3
804	    style m3 fill:#eef,stroke:#33c
805	```
806	
807	The challenge: express this matrix **entirely at compile time**, with static
808	dispatch, so that calling `extended_unlock()` on a basic probe or
809	`read_memory()` on an unlocked-but-not-extended handle is a compile error.
810	
811	### The Solution: `Jtag<V, S>` with Marker Traits
812	
813	**Step 1 — State tokens and capability markers:**
814	
815	```rust,ignore
816	use std::marker::PhantomData;
817	
818	// Zero-sized state tokens — no runtime cost
819	struct Locked;
820	struct Unlocked;
821	struct ExtendedUnlocked;
822	
823	// Marker traits express which capabilities each state has
824	trait HasRegAccess {}
825	impl HasRegAccess for Unlocked {}
826	impl HasRegAccess for ExtendedUnlocked {}
827	
828	trait HasMemAccess {}
829	impl HasMemAccess for ExtendedUnlocked {}
830	```
831	
832	> **Why marker traits, not just concrete states?**
833	> Writing `impl<V, S: HasRegAccess> Jtag<V, S>` means `read_reg()` works in
834	> *any* state with register access — today that's `Unlocked` and `ExtendedUnlocked`,
835	> but if you add `DebugHalted` tomorrow, you just add one line:
836	> `impl HasRegAccess for DebugHalted {}`. Every register function works with
837	> it automatically — zero code changes.
838	
839	**Step 2 — Vendor traits (raw operations):**
840	
841	```rust,ignore
842	// Every probe vendor implements these
843	trait JtagVendor {
844	    fn raw_unlock(&mut self);
845	    fn raw_read_reg(&self, addr: u32) -> u32;
846	    fn raw_write_reg(&mut self, addr: u32, val: u32);
847	}
848	
849	// Vendors with memory access also implement this super-trait
850	trait JtagMemoryVendor: JtagVendor {
851	    fn raw_extended_unlock(&mut self);
852	    fn raw_read_memory(&self, addr: u64, buf: &mut [u8]);
853	    fn raw_write_memory(&mut self, addr: u64, data: &[u8]);
854	}
855	```
856	
857	**Step 3 — The wrapper with conditional `impl` blocks:**
858	
859	```rust,ignore
860	struct Jtag<V, S = Locked> {
861	    vendor: V,
862	    _state: PhantomData<S>,
863	}
864	
865	// Construction — always starts Locked
866	impl<V: JtagVendor> Jtag<V, Locked> {
867	    fn new(vendor: V) -> Self {
868	        Jtag { vendor, _state: PhantomData }
869	    }
870	
871	    fn unlock(mut self) -> Jtag<V, Unlocked> {
872	        self.vendor.raw_unlock();
873	        Jtag { vendor: self.vendor, _state: PhantomData }
874	    }
875	}
876	
877	// Register I/O — any vendor, any state with HasRegAccess
878	impl<V: JtagVendor, S: HasRegAccess> Jtag<V, S> {
879	    fn read_reg(&self, addr: u32) -> u32 {
880	        self.vendor.raw_read_reg(addr)
881	    }
882	    fn write_reg(&mut self, addr: u32, val: u32) {
883	        self.vendor.raw_write_reg(addr, val);
884	    }
885	}
886	
887	// Extended unlock — only memory-capable vendors, only from Unlocked
888	impl<V: JtagMemoryVendor> Jtag<V, Unlocked> {
889	    fn extended_unlock(mut self) -> Jtag<V, ExtendedUnlocked> {
890	        self.vendor.raw_extended_unlock();
891	        Jtag { vendor: self.vendor, _state: PhantomData }
892	    }
893	}
894	
895	// Memory I/O — only memory-capable vendors, only ExtendedUnlocked
896	impl<V: JtagMemoryVendor, S: HasMemAccess> Jtag<V, S> {
897	    fn read_memory(&self, addr: u64, buf: &mut [u8]) {
898	        self.vendor.raw_read_memory(addr, buf);
899	    }
900	    fn write_memory(&mut self, addr: u64, data: &[u8]) {
901	        self.vendor.raw_write_memory(addr, data);
902	    }
903	}
904	```
905	
906	Each `impl` block encodes one cell (or row) of the capability matrix.
907	The compiler enforces the matrix — no runtime checks anywhere.
908	
909	### Vendor Implementations
910	
911	Adding a vendor means implementing raw methods on **one struct** — no
912	per-state struct duplication, no delegation boilerplate:
913	
914	```rust,ignore
915	// Vendor A: basic probe — register access only
916	struct BasicProbe { port: u16 }
917	
918	impl JtagVendor for BasicProbe {
919	    fn raw_unlock(&mut self)                    { /* TAP reset sequence */ }
920	    fn raw_read_reg(&self, addr: u32) -> u32    { /* DR scan */  0 }
921	    fn raw_write_reg(&mut self, addr: u32, val: u32) { /* DR scan */ }
922	}
923	// BasicProbe does NOT impl JtagMemoryVendor.
924	// extended_unlock() will not compile on Jtag<BasicProbe, _>.
925	
926	// Vendor B: full-featured probe — registers + memory
927	struct DapProbe { serial: String }
928	
929	impl JtagVendor for DapProbe {
930	    fn raw_unlock(&mut self)                    { /* SWD switch, read DPIDR */ }
931	    fn raw_read_reg(&self, addr: u32) -> u32    { /* AP register read */ 0 }
932	    fn raw_write_reg(&mut self, addr: u32, val: u32) { /* AP register write */ }
933	}
934	
935	impl JtagMemoryVendor for DapProbe {
936	    fn raw_extended_unlock(&mut self)           { /* select MEM-AP, power up */ }
937	    fn raw_read_memory(&self, addr: u64, buf: &mut [u8])  { /* MEM-AP read */ }
938	    fn raw_write_memory(&mut self, addr: u64, data: &[u8]) { /* MEM-AP write */ }
939	}
940	```
941	
942	### What the Compiler Prevents
943	
944	| Attempt | Error | Why |
945	|---------|-------|-----|
946	| `Jtag<_, Locked>::read_reg()` | no method `read_reg` | `Locked` doesn't impl `HasRegAccess` |
947	| `Jtag<BasicProbe, _>::extended_unlock()` | no method `extended_unlock` | `BasicProbe` doesn't impl `JtagMemoryVendor` |
948	| `Jtag<_, Unlocked>::read_memory()` | no method `read_memory` | `Unlocked` doesn't impl `HasMemAccess` |
949	| Calling `unlock()` twice | value used after move | `unlock()` consumes `self` |
950	
951	All four errors are caught **at compile time**. No panics, no `Option`, no runtime state enum.
952	
953	### Writing Generic Functions
954	
955	Functions bind only the axes they care about:
956	
957	```rust,ignore
958	/// Works with ANY vendor, ANY state that grants register access.
959	fn read_idcode<V: JtagVendor, S: HasRegAccess>(jtag: &Jtag<V, S>) -> u32 {
960	    jtag.read_reg(0x00)
961	}
962	
963	/// Only compiles for memory-capable vendors in ExtendedUnlocked state.
964	fn dump_firmware<V: JtagMemoryVendor, S: HasMemAccess>(jtag: &Jtag<V, S>) {
965	    let mut buf = [0u8; 256];
966	    jtag.read_memory(0x0800_0000, &mut buf);
967	}
968	```
969	
970	`read_idcode` doesn't care whether you're in `Unlocked` or `ExtendedUnlocked` —
971	it only requires `HasRegAccess`. This is where marker traits pay off over
972	hardcoding specific states in signatures.
973	
974	### Same Pattern, Different Domain: Storage Backends
975	
976	The dual-axis technique isn't hardware-specific. Here's the same structure
977	for a storage layer where some backends support transactions:
978	
979	```rust,ignore
980	// States
981	struct Closed;
982	struct Open;
983	struct InTransaction;
984	
985	trait HasReadWrite {}
986	impl HasReadWrite for Open {}
987	impl HasReadWrite for InTransaction {}
988	
989	// Vendor traits
990	trait StorageBackend {
991	    fn raw_open(&mut self);
992	    fn raw_read(&self, key: &[u8]) -> Option<Vec<u8>>;
993	    fn raw_write(&mut self, key: &[u8], value: &[u8]);
994	}
995	
996	trait TransactionalBackend: StorageBackend {
997	    fn raw_begin(&mut self);
998	    fn raw_commit(&mut self);
999	    fn raw_rollback(&mut self);
1000	}
1001	
1002	// Wrapper
1003	struct Store<B, S = Closed> { backend: B, _s: PhantomData<S> }
1004	
1005	impl<B: StorageBackend> Store<B, Closed> {
1006	    fn open(mut self) -> Store<B, Open> { self.backend.raw_open(); /* ... */ todo!() }
1007	}
1008	impl<B: StorageBackend, S: HasReadWrite> Store<B, S> {
1009	    fn read(&self, key: &[u8]) -> Option<Vec<u8>>  { self.backend.raw_read(key) }
1010	    fn write(&mut self, key: &[u8], val: &[u8])    { self.backend.raw_write(key, val) }
1011	}
1012	impl<B: TransactionalBackend> Store<B, Open> {
1013	    fn begin(mut self) -> Store<B, InTransaction>   { /* ... */ todo!() }
1014	}
1015	impl<B: TransactionalBackend> Store<B, InTransaction> {
1016	    fn commit(mut self) -> Store<B, Open>           { /* ... */ todo!() }
1017	    fn rollback(mut self) -> Store<B, Open>         { /* ... */ todo!() }
1018	}
1019	```
1020	
1021	A flat-file backend implements `StorageBackend` only — `begin()` won't
1022	compile. A database backend adds `TransactionalBackend` — the full
1023	`Open → InTransaction → Open` cycle becomes available.
1024	
1025	### When to Reach for This Pattern
1026	
1027	| Signal | Why dual-axis fits |
1028	|--------|--------------------|
1029	| Two independent axes: "who provides it" and "what state is it in" | The `impl` block matrix directly encodes both |
1030	| Some providers have strictly more capabilities than others | Super-trait (`MemoryVendor: Vendor`) + conditional `impl` |
1031	| Misusing state or capability is a safety/correctness bug | Compile-time prevention > runtime checks |
1032	| You want static dispatch (no vtables) | `PhantomData` + generics = zero-cost |
1033	
1034	| Signal | Consider something simpler |
1035	|--------|---------------------------|
1036	| Only one axis varies (state OR vendor, not both) | Single-axis typestate or plain trait objects |
1037	| Three or more independent axes | Config Trait Pattern (above) bundles axes into associated types |
1038	| Runtime polymorphism is acceptable | `enum` state + `dyn` dispatch is simpler |
1039	
1040	> **When two axes become three or more:**
1041	> If you find yourself writing `Handle<V, S, D, T>` — vendor, state, debug
1042	> level, transport — the generic parameter list is telling you something.
1043	> Consider collapsing the *vendor* axis into an associated-type config trait
1044	> (the [Config Trait Pattern](#config-trait-pattern--taming-generic-parameter-explosion)
1045	> from earlier in this chapter), keeping only the *state* axis as a generic
1046	> parameter: `Handle<Cfg, S>`. The config trait bundles `type Vendor`, `type Transport`, etc.
1047	> into one parameter, and the state axis retains its compile-time transition guarantees.
1048	> This is a natural evolution, not a rewrite — you lift vendor-related types
1049	> into `Cfg` and leave the typestate machinery untouched.
1050	
1051	> **Key Takeaway:** The dual-axis pattern is the intersection of typestate and
1052	> trait-based abstraction. Each `impl` block maps to one cell of the
1053	> (vendor × state) matrix. The compiler enforces the entire matrix — no
1054	> runtime state checks, no impossible-state panics, no cost.
1055	
1056	---
1057	
1058	### Exercise: Type-Safe State Machine ★★ (~30 min)
1059	
1060	Build a traffic light state machine using the type-state pattern. The light must transition `Red → Green → Yellow → Red` and no other order should be possible.
1061	
1062	<details>
1063	<summary>🔑 Solution</summary>
1064	
1065	```rust
1066	use std::marker::PhantomData;
1067	
1068	struct Red;
1069	struct Green;
1070	struct Yellow;
1071	
1072	struct TrafficLight<State> {
1073	    _state: PhantomData<State>,
1074	}
1075	
1076	impl TrafficLight<Red> {
1077	    fn new() -> Self {
1078	        println!("🔴 Red — STOP");
1079	        TrafficLight { _state: PhantomData }
1080	    }
1081	
1082	    fn go(self) -> TrafficLight<Green> {
1083	        println!("🟢 Green — GO");
1084	        TrafficLight { _state: PhantomData }
1085	    }
1086	}
1087	
1088	impl TrafficLight<Green> {
1089	    fn caution(self) -> TrafficLight<Yellow> {
1090	        println!("🟡 Yellow — CAUTION");
1091	        TrafficLight { _state: PhantomData }
1092	    }
1093	}
1094	
1095	impl TrafficLight<Yellow> {
1096	    fn stop(self) -> TrafficLight<Red> {
1097	        println!("🔴 Red — STOP");
1098	        TrafficLight { _state: PhantomData }
1099	    }
1100	}
1101	
1102	fn main() {
1103	    let light = TrafficLight::new(); // Red
1104	    let light = light.go();          // Green
1105	    let light = light.caution();     // Yellow
1106	    let _light = light.stop();       // Red
1107	
1108	    // light.caution(); // ❌ Compile error: no method `caution` on Red
1109	    // TrafficLight::new().stop(); // ❌ Compile error: no method `stop` on Red
1110	}
1111	```
1112	
1113	**Key takeaway**: Invalid transitions are compile errors, not runtime panics.
1114	
1115	</details>
1116	
1117	***
1118	
1119

