82	/// IPMI session parameterised by its current state.
83	/// The state exists ONLY in the type system (PhantomData is zero-sized).
84	pub struct IpmiSession<State> {
85	    transport: String,     // e.g., "192.168.1.100"
86	    session_id: Option<u32>,
87	    _state: PhantomData<State>,
88	}
