492	use std::marker::PhantomData;
493	
494	pub struct Attached;
495	pub struct Powered;
496	pub struct Default;
497	pub struct Addressed;
498	pub struct Configured;
499	
500	pub struct UsbDevice<State> {
501	    address: u8,
502	    _state: PhantomData<State>,
503	}
504	
505	impl UsbDevice<Attached> {
506	    pub fn new() -> Self {
507	        UsbDevice { address: 0, _state: PhantomData }
508	    }
509	    pub fn power_on(self) -> UsbDevice<Powered> {
510	        UsbDevice { address: self.address, _state: PhantomData }
511	    }
512	}
513	
514	impl UsbDevice<Powered> {
515	    pub fn reset(self) -> UsbDevice<Default> {
516	        UsbDevice { address: self.address, _state: PhantomData }
517	    }
518	}
519	
520	impl UsbDevice<Default> {
521	    pub fn set_address(self, addr: u8) -> UsbDevice<Addressed> {
522	        UsbDevice { address: addr, _state: PhantomData }
523	    }
524	}
